mapper.select:
SELECT c.FINPROD_ID AS finprodId, /**资产代码(金融产品代码)**/ c.FINPROD_ABBR AS finprodAbbr, /**债券简称(金融产品简称)**/
a.VALUE_DATE AS valueDate, /**估值日**/ '' AS lastPeriod, /**剩余期限**/ a.CLOSE_PRICE AS cloPrice, /**收盘价**/ a.AVERAGE_PRICE AS avgPrice, /**平均价**/ a.BUY_ONE_PRICE AS buyOnePrice, /**买一价**/ a.SELL_ONE_PRICE AS sellOnePrice, /**卖一价**/ a.MAX_PRICE AS maxPrice, /**最高价**/ a.MIN_PRICE AS minPrice /**最低价**/ FROM mst_BOND_MARKET_INFO a INNER JOIN FIN_PRODUCT c ON a.SEC_ID=c.FINPROD_MARKET_ID WHERE 1 = 1
AND c.FINPROD_TYPE = #{finprodType}
AND c.FINPROD_ID LIKE concat_ws('','%',#{finprodId} ,'%')
AND c.FINPROD_ABBR LIKE concat_ws('','%',#{finprodAbbr},'%')
AND a.VALUE_DATE >= #{valueDateBegin}
AND a.VALUE_DATE <= #{valueDateEnd}
